src/styles/global.css.content:
@custom-variant dark (&:where([data-theme='dark'], [data-theme='dark'] *));

@layer base, starlight, theme, black, components, utilities;
@import 'tailwindcss/preflight.css' layer(base);
@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/utilities.css' layer(utilities);

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
}

:root {
  --content-width: 50rem;
  --sl-content-width: var(--content-width);
  --sl-sidebar-width: 21rem;

  --muted: oklch(0.97 0 0);

  --color-1: oklch(66.2% 0.225 25.9);
  --color-2: oklch(60.4% 0.26 302);
  --color-3: oklch(69.6% 0.165 251);
  --color-4: oklch(80.2% 0.134 225);
  --color-5: oklch(90.7% 0.231 133);
}

[data-theme='dark'] {
  --muted: oklch(0.269 0 0);
}

/* 首页（splash、无 sidebar）：内容 70rem 宽并始终居中。
   starlight 的 .sl-container 居中（margin-inline: auto）只在 ≥72rem 视口生效，
   窄视口下会贴左，这里无条件居中；宽度不用 --content-width（50rem）改从
   官方页面的 67.5rem 略放宽 */
html:root:not([data-has-sidebar]) {
  --sl-content-width: 70rem;
}
html:root:not([data-has-sidebar]) .sl-container {
  margin-inline: auto;
}

[data-has-sidebar][data-has-toc] .main-pane {
  max-width: none;
  flex: 0 1 auto;
  margin-inline: 0;
  --sl-content-margin-inline: auto;
}

.content-panel {
  padding: 1.5rem var(--sl-content-pad-x);
}

.main-frame {
  padding-inline-start: var(--sl-content-inline-start);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-border: var(--border);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover-background);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--red);
  --color-destructive-foreground: var(--primary-foreground);
  --color-input: var(--border);
  --color-ring: var(--ring);

  --animate-aurora: aurora 8s ease-in-out infinite alternate;
  --animate-blink-cursor: blink-cursor 1.2s step-end infinite;
  --animate-gradient: gradient 8s linear infinite;
  --animate-line: line 2s linear infinite;
  --animate-line-shadow: line-shadow 15s linear infinite;
  --animate-marquee: marquee var(--duration) infinite linear;
  --animate-marquee-vertical: marquee-vertical var(--duration) linear infinite;
  --animate-meteor: meteor 5s linear infinite;
  --animate-orbit: orbit calc(var(--duration) * 1s) linear infinite;
  --animate-ping: ping 1s cubic-bezier(0, 0, 0.2, 1) infinite;
  --animate-rainbow: rainbow var(--speed, 2s) infinite linear;
  --animate-ripple: ripple var(--duration, 2s) ease calc(var(--i, 0) * 0.2s) infinite;
  --animate-rippling: rippling var(--duration, 0.6s) ease-out;
  --animate-shimmer-slide: shimmer-slide var(--speed) ease-in-out infinite alternate;
  --animate-shiny-text: shiny-text 8s infinite;
  --animate-shine: shine var(--duration) infinite linear;
  --animate-spin-around: spin-around calc(var(--speed) * 2) infinite linear;
  --animate-pulse-ring: pulse-ring var(--duration, 1.5s) ease-out infinite;
  --animate-background-position-spin: background-position-spin 3000ms infinite alternate;
  --animate-warp-beam: warp-beam var(--beam-duration) linear infinite;
  --animate-pulse: pulse var(--duration) ease-out infinite;
  --animate-pulse-ripple: pulse-ripple var(--duration) cubic-bezier(0.16, 1, 0.3, 1) infinite;
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;

  @keyframes pulse {
    0%,
    100% {
      box-shadow: 0 0 0 0 var(--pulse-color, oklch(from var(--bg) l c h / 0.5));
    }
    50% {
      box-shadow: 0 0 0 var(--distance) var(--pulse-color, oklch(from var(--bg) l c h / 0.5));
    }
  }

  @keyframes pulse-ripple {
    0% {
      box-shadow: 0 0 0 0 oklch(from var(--pulse-color, var(--bg)) l c h / 1);
    }
    100% {
      box-shadow: 0 0 0 var(--distance) oklch(from var(--pulse-color, var(--bg)) l c h / 0);
    }
  }

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--kb-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--kb-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

@keyframes aurora {
  0% {
    background-position: 0% 50%;
    transform: rotate(-5deg) scale(0.9);
  }
  25% {
    background-position: 50% 100%;
    transform: rotate(5deg) scale(1.1);
  }
  50% {
    background-position: 100% 50%;
    transform: rotate(-3deg) scale(0.95);
  }
  75% {
    background-position: 50% 0%;
    transform: rotate(3deg) scale(1.05);
  }
  100% {
    background-position: 0% 50%;
    transform: rotate(-5deg) scale(0.9);
  }
}

@keyframes blink-cursor {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

@keyframes gradient {
  to {
    background-position: var(--bg-size, 300%) 0;
  }
}

@keyframes line {
  0% {
    mask-position-x: 0%;
  }
  100% {
    mask-position-x: 100%;
  }
}

@keyframes line-shadow {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 100% -100%;
  }
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(calc(-100% - var(--gap)));
  }
}

@keyframes marquee-vertical {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(calc(-100% - var(--gap)));
  }
}

@keyframes meteor {
  0% {
    transform: rotate(var(--angle)) translateX(0);
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    transform: rotate(var(--angle)) translateX(-500px);
    opacity: 0;
  }
}

@keyframes orbit {
  0% {
    transform: rotate(calc(var(--angle) * 1deg)) translateY(calc(var(--radius) * 1px))
      rotate(calc(var(--angle) * -1deg));
  }
  100% {
    transform: rotate(calc(var(--angle) * 1deg + 360deg)) translateY(calc(var(--radius) * 1px))
      rotate(calc((var(--angle) * -1deg) - 360deg));
  }
}

@keyframes ping {
  75%,
  100% {
    transform: scale(2);
    opacity: 0;
  }
}

@keyframes rainbow {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes ripple {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    transform: translate(-50%, -50%) scale(0.9);
  }
}

@keyframes rippling {
  0% {
    opacity: 1;
  }
  100% {
    transform: scale(2);
    opacity: 0;
  }
}

@keyframes shimmer-slide {
  to {
    transform: translate(calc(100cqw - 100%), 0);
  }
}

@keyframes shiny-text {
  0%,
  90%,
  100% {
    background-position: calc(-100% - var(--shiny-width)) 0;
  }
  30%,
  60% {
    background-position: calc(100% + var(--shiny-width)) 0;
  }
}

@keyframes shine {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

@keyframes spin-around {
  0% {
    transform: translateZ(0) rotate(0);
  }
  15%,
  35% {
    transform: translateZ(0) rotate(90deg);
  }
  65%,
  85% {
    transform: translateZ(0) rotate(270deg);
  }
  100% {
    transform: translateZ(0) rotate(360deg);
  }
}

@keyframes pulse-ring {
  0% {
    box-shadow: 0 0 0 0 var(--ring-color, hsl(240, 5%, 85%, 0.5));
  }
  100% {
    box-shadow: 0 0 0 var(--ring-distance, 12px) transparent;
  }
}

@keyframes background-position-spin {
  0% {
    background-position: top center;
  }
  100% {
    background-position: bottom center;
  }
}

@keyframes warp-beam {
  from {
    transform: translateX(-50%) translateY(100cqmax);
  }
  to {
    transform: translateX(-50%) translateY(-100%);
  }
}

::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
}

/* Shiki dual-theme: Starlight [data-theme] activates the correct side */
[data-theme='dark'] .shiki {
  background-color: var(--shiki-dark-bg, transparent);
  color: var(--shiki-dark, currentColor);
}
[data-theme='dark'] .shiki code span {
  color: var(--shiki-dark, currentColor);
}

[data-theme='light'] .shiki {
  background-color: var(--shiki-light-bg, transparent);
  color: var(--shiki-light, currentColor);
}
[data-theme='light'] .shiki code span {
  color: var(--shiki-light, currentColor);
}

/*
 * starlight-theme-black 的 `.sl-markdown-content *` 在 ≥40rem 视口强制
 * font-size: 15px，会误伤 demo 预览容器（.not-content）内的所有元素。
 * 这里恢复 demo 区域的继承：components 层（高于 black）压过 15px，
 * 同时用 :where 把特异性归零，确保 demo 内 text-* 工具类的字号不受影响。
 */
@layer components {
  .not-content,
  :where(.not-content) * {
    font-size: inherit;
  }
}

/* 侧边栏链接禁用折行：容器宽度与长标题零余量，字体回退/DPI 差异会导致意外换行 */
#starlight__sidebar a {
  white-space: nowrap;
}

src/registry/magicui/marquee.tsx.content:
import type { JSX } from 'solid-js'
import { For, mergeProps, splitProps } from 'solid-js'
import { cn } from '@/lib/utils'

interface MarqueeProps extends JSX.HTMLAttributes<HTMLDivElement> {
  /**
   * Optional CSS class name to apply custom styles
   */
  class?: string
  /**
   * Whether to reverse the animation direction
   * @default false
   */
  reverse?: boolean
  /**
   * Whether to pause the animation on hover
   * @default false
   */
  pauseOnHover?: boolean
  /**
   * Content to be displayed in the marquee
   */
  children: JSX.Element
  /**
   * Whether to animate vertically instead of horizontally
   * @default false
   */
  vertical?: boolean
  /**
   * Number of times to repeat the content
   * @default 4
   */
  repeat?: number
}

export function Marquee(props: MarqueeProps) {
  const merged = mergeProps({ reverse: false, pauseOnHover: false, vertical: false, repeat: 4 }, props)
  const [local, rest] = splitProps(merged, ['reverse', 'pauseOnHover', 'children', 'vertical', 'repeat', 'class'])

  return (
    <div
      class={cn(`
        group flex gap-(--gap) overflow-hidden p-2 [--duration:40s] [--gap:1rem]
      `, {
        'flex-row': !local.vertical,
        'flex-col': local.vertical,
      }, local.class)}
      {...rest}
    >
      <For each={Array.from({ length: local.repeat })}>
        {() => (
          <div
            class={cn('flex shrink-0 justify-around gap-(--gap)', {
              'animate-marquee flex-row': !local.vertical,
              'animate-marquee-vertical flex-col': local.vertical,
              'group-hover:[animation-play-state:paused]': local.pauseOnHover,
              '[animation-direction:reverse]': local.reverse,
            })}
          >
            {local.children}
          </div>
        )}
      </For>
    </div>
  )
}

src/registry/magicui/ripple-button.tsx.content:
import type { ComponentProps, JSX } from 'solid-js'
import { createEffect, createSignal, For, mergeProps, onCleanup, splitProps } from 'solid-js'

import { cn } from '@/lib/utils'

interface RippleButtonProps extends Omit<ComponentProps<'button'>, 'onClick'> {
  onClick?: (event: MouseEvent) => void
  rippleColor?: string
  duration?: string
}

interface RippleButtonRipple {
  x: number
  y: number
  size: number
  key: number
}

export function RippleButton(props: RippleButtonProps) {
  const merged = mergeProps(
    {
      rippleColor: '#ffffff',
      duration: '600ms',
    },
    props,
  )
  const [local, rest] = splitProps(merged, ['class', 'children', 'rippleColor', 'duration', 'onClick'])
  const [buttonRipples, setButtonRipples] = createSignal<RippleButtonRipple[]>([])

  const createRipple = (event: MouseEvent) => {
    const button = event.currentTarget as HTMLButtonElement
    const rect = button.getBoundingClientRect()
    const size = Math.max(rect.width, rect.height)
    const x = event.clientX - rect.left - size / 2
    const y = event.clientY - rect.top - size / 2

    const newRipple = { x, y, size, key: Date.now() }
    setButtonRipples(prevRipples => [...prevRipples, newRipple])
  }

  const handleClick = (event: MouseEvent) => {
    createRipple(event)
    local.onClick?.(event)
  }

  createEffect(() => {
    let timeout: ReturnType<typeof setTimeout> | null = null

    if (buttonRipples().length > 0) {
      const lastRipple = buttonRipples()[buttonRipples().length - 1]
      timeout = setTimeout(() => {
        setButtonRipples(prevRipples =>
          prevRipples.filter(ripple => ripple.key !== lastRipple.key),
        )
      }, Number.parseInt(local.duration))
    }

    onCleanup(() => {
      if (timeout !== null) {
        clearTimeout(timeout)
      }
    })
  })

  return (
    <button
      class={cn(
        `
          relative flex cursor-pointer items-center justify-center
          overflow-hidden rounded-lg border-2 bg-background px-4 py-2
          text-center text-primary
        `,
        local.class,
      )}
      onClick={handleClick}
      {...rest}
    >
      <div class="relative z-10">{local.children}</div>
      <span class="pointer-events-none absolute inset-0">
        <For each={buttonRipples()}>
          {ripple => (
            <span
              class="
                absolute animate-rippling rounded-full bg-background opacity-30
              "
              style={{
                'width': `${ripple.size}px`,
                'height': `${ripple.size}px`,
                'top': `${ripple.y}px`,
                'left': `${ripple.x}px`,
                'background-color': local.rippleColor,
                'transform': 'scale(0)',
                '--duration': local.duration,
              } as JSX.CSSProperties}
            />
          )}
        </For>
      </span>
    </button>
  )
}

