    --popover-background: var(--gray-7);
    --popover-foreground: var(--foreground);
    --markdown-foreground: var(--gray-2);

    /* backdrop */
    ::backdrop {
      --sl-color-backdrop-overlay: color-mix(in oklab, var(--background) 80%, transparent);
    }

    ::selection {
      background-color: var(--selection);
      color: var(--selection-foreground);
    }
  }

  header.header {
    border-bottom: none;
  }

  .site-title {
    gap: 0.5rem;
    font-weight: 700;
    font-size: 1rem;
    display: none;

    @media (min-width: 64rem) {
      display: flex;
    }
  }

  .site-title > img {
    max-height: 32px;
    max-width: 32px;
  }

  .social-icons::after {
    content: '';
    height: 1rem;
    border-inline-end: 1px solid var(--sl-color-gray-5);
  }

  nav.sidebar {
    display: none;
    @media (min-width: 64rem) {
      display: flex;
    }
  }

  .sidebar-pane {
    display: flex;
    overscroll-behavior: none;
    overflow: hidden;
    flex-direction: column;
    height: calc(100svh - 10rem);
    overflow-y: hidden;
    border-inline-end: none;
    padding: 0;
    top: calc(var(--sl-nav-height) + 0.6rem);
  }

  .sidebar-pane::after {
    position: absolute;
    content: '';
    top: 0rem;
    right: 0rem;
    bottom: 0;
    width: 1px;
    background: linear-gradient(to bottom, transparent 0%, var(--border) 50%, transparent 100%);
    display: none;
    z-index: 1;

    @media (min-width: 1024px) {
      display: flex;
    }
  }

  .sidebar-content {
    padding: 0;
    padding-left: calc(var(--spacing) * 2.5);
    width: calc(var(--spacing) * 56);
    overflow: auto;
    overflow-x: hidden;
    min-height: 0;
    gap: calc(var(--spacing) * 2);
    flex-direction: column;
    scrollbar-width: none;
    display: flex;

    & ul {
      list-style: none;
      padding: 0;
      margin: 0;
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: calc(var(--spacing) * 1);
    }

    & li {
      overflow-wrap: anywhere;
    }

    & summary::marker,
    & summary::-webkit-details-marker {
      display: none;
    }

    --_scroll-fade-size-t: var(--scroll-fade-t-size, var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10))));
    --_scroll-fade-size-b: var(--scroll-fade-b-size, var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10))));
    --scroll-fade-block: linear-gradient(
      to bottom,
      transparent 0,
      #000 var(--scroll-fade-t, 0px),
      #000 calc(100% - var(--scroll-fade-b, 0px)),
      transparent 100%
    );

    -webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
    mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-composite: source-in;
    mask-composite: intersect;

    @supports (animation-timeline: scroll()) {
      animation:
        1ms ease-in-out scroll-fade-reveal-t,
        1ms ease-in-out scroll-fade-reveal-b;
      animation-timeline: scroll(self y), scroll(self y);
      animation-range:
        0 var(--scroll-fade-reveal, calc(var(--spacing) * 24)),
        calc(100% - var(--scroll-fade-reveal, calc(var(--spacing) * 24))) 100%;
      animation-fill-mode: both;
    }
  }

  @keyframes scroll-fade-reveal-t {
    0% {
      --scroll-fade-t: 0px;
    }
    100% {
      --scroll-fade-t: var(--_scroll-fade-size-t, var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10))));
    }
  }

  @keyframes scroll-fade-reveal-b {
    0% {
      --scroll-fade-b: var(--_scroll-fade-size-b, var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10))));
    }
    100% {
      --scroll-fade-b: 0px;
    }
  }

  site-search {
    display: none;
    justify-content: flex-end;
    align-items: center;
    width: 100%;
    @media (min-width: 48rem) {
      display: flex;
    }
  }

  site-search::after {
    content: '';
    display: block;
    height: 1rem;
    margin-left: 1rem;
    border-inline-end: 1px solid var(--sl-color-gray-5);
  }

  site-search > button[data-open-modal] {
    background-color: var(--muted);
    border: none;
    border-radius: var(--radius);
    padding-left: calc(var(--spacing) * 3);
    padding-block: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 4);
    height: 2rem;
    margin: 0;
    color: var(--foreground);
    cursor: default;
    font-weight: 400;
    font-size: 0.875rem;
    line-height: 1.25rem;

    @media (min-width: 48rem) {
      width: calc(var(--spacing) * 48);
    }
    @media (min-width: 64rem) {
      width: calc(var(--spacing) * 40);
    }
    @media (min-width: 80rem) {
      width: calc(var(--spacing) * 64);
    }
  }

  site-search > button[data-open-modal] svg,
  site-search > button > kbd {
    display: none;
  }

  site-search > button > span {
    display: block;
  }

  .right-sidebar-container {
    width: calc(var(--spacing) * 72);
    display: none;
    padding-inline: calc(var(--spacing) * 8);
    @media (min-width: 80rem) {
      display: flex;
    }
  }

  .right-sidebar {
    width: calc(var(--spacing) * 72);
    top: calc(var(--spacing) * 8);
    height: 90svh;
    border-inline-start: none;
  }

  .right-sidebar-panel {
    padding-top: 0;
    padding-inline: calc(var(--spacing) * 2);
    padding-bottom: calc(var(--spacing) * 4);
  }

  .right-group {
    display: flex;
  }

  .content-panel {
    padding: 0;
  }

  .content-panel + .content-panel {
    border-top: none;
  }

  mobile-starlight-toc {
    display: none;
  }

  .main-frame {
    padding-top: var(--sl-nav-height);
    padding-inline-start: 0;
    @media (min-width: 64rem) {
      padding-inline-start: var(--sl-content-inline-start);
    }
  }

  [data-has-sidebar] .header {
    padding-inline-end: var(--sl-nav-pad-y);
  }

  [data-has-sidebar][data-has-toc] .main-pane {
    max-width: calc(var(--spacing) * 160);
    padding-block: calc(var(--spacing) * 6);

    @media (min-width: 64rem) {
      padding-block: calc(var(--spacing) * 8);
      padding-top: calc(calc(var(--spacing) * 4) + calc(var(--spacing) * 8));
    }
  }

  .main-pane {
    flex: 1;
    padding-inline: calc(var(--spacing) * 4);
    min-width: calc(var(--spacing) * 0);
    margin-inline: auto;

    @media (min-width: 48rem) {
      padding-inline: calc(var(--spacing) * 0);
    }
  }

  .main-pane > main {
    display: flex;
    flex-direction: column;
    gap: calc(var(--spacing) * 6);
  }

  starlight-toc h2 {
    color: var(--muted-foreground);
    font-weight: 500;
    font-size: 0.75rem;
    line-height: calc(1 / 0.75);
  }

  starlight-toc a {
    color: var(--muted-foreground);
    font-size: 0.8rem;
    padding-inline: calc(0.25rem * var(--depth) + var(--pad-inline)) var(--pad-inline);
  }

  starlight-toc a[aria-current='true'] {
    color: var(--foreground);
  }

  starlight-toc > nav > ul > li > a {
    padding-inline-start: 0;
  }

  footer > .meta {
    flex-direction: column-reverse;
  }

  footer > .meta > :first-child {
    margin-left: auto;
  }

  /* global typography refinements */
  * :not(pre) > code {
    border-color: var(--border);
  }

  html {
    scrollbar-gutter: stable;
  }

  body {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* link styles for markdown content */
  .sl-markdown-content a:not([class]) {
    text-decoration: underline;
    text-underline-offset: calc(var(--spacing) * 1);
    text-decoration-color: var(--muted-foreground);
    color: var(--foreground);
    font-weight: 500;
  }

  .sl-markdown-content a:not([class]):hover {
    text-decoration-color: var(--foreground);
  }

  /* paragraph styles */
  .sl-markdown-content * {
    @media (min-width: 40rem) {
      font-size: 15px;
    }
  }

  .sl-markdown-content :is(h1, h2, h3, h4, h5, h6) {
    font-weight: 500;
    letter-spacing: var(--tracking-tight);
    color: var(--foreground);
  }

  .sl-markdown-content h1 {
    font-size: 1.875rem;
    line-height: 2.25rem;
    font-weight: 600;
  }

  .sl-markdown-content h2 {
    font-size: 1.25rem;
    line-height: 1.75rem;
    padding-top: calc(var(--spacing) * 6);
    margin-top: calc(var(--spacing) * 12);
  }

  .sl-markdown-content h3 {
    font-size: 1.125rem;
    line-height: 1.75rem;
  }
  .sl-markdown-content h4 {
    font-size: 1rem;
    line-height: 1.5rem;
  }
  .sl-markdown-content :is(h5, h6) {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }

  .sl-markdown-content .sl-heading-wrapper {
    --sl-anchor-icon-gap: 0.375rem;
  }

  .sl-markdown-content :not(h1, h2, h3, h4, h5, h6, .sl-heading-wrapper) + :is(.sl-heading-wrapper) {
    margin-top: calc(var(--spacing) * 12);
  }

  .sl-markdown-content a[data-slot='button'] {
    margin-top: var(--sl-content-gap-y);
  }

  .sl-markdown-content a[data-slot='button'] + :not(a, strong, em, del, span, input, code, br, :where(.not-content *)) {
    margin-top: var(--sl-content-gap-y);
  }

  .sl-markdown-content .sl-heading-wrapper.level-h1 {
    --sl-anchor-icon-size: 1.125rem;
    --sl-anchor-icon-space: calc(var(--sl-anchor-icon-size) + var(--sl-anchor-icon-gap));
    line-height: 2.25rem;
  }

  .sl-markdown-content .sl-heading-wrapper.level-h2 {
    --sl-anchor-icon-size: calc(var(--spacing) * 5);
    --sl-anchor-icon-space: calc(var(--sl-anchor-icon-size) + var(--sl-anchor-icon-gap));
    line-height: 1.75rem;
  }

  .sl-markdown-content .sl-heading-wrapper.level-h3 {
    --sl-anchor-icon-size: 0.875rem;
    --sl-anchor-icon-space: calc(var(--sl-anchor-icon-size) + var(--sl-anchor-icon-gap));
    line-height: 1.75rem;
  }

  .sl-markdown-content .sl-heading-wrapper.level-h4 {
    --sl-anchor-icon-size: 0.875rem;
    --sl-anchor-icon-space: calc(var(--sl-anchor-icon-size) + var(--sl-anchor-icon-gap));
    line-height: 1.5rem;
  }

  .sl-markdown-content .sl-heading-wrapper:is(.level-h5, .level-h6) {
    --sl-anchor-icon-size: 0.75rem;
    --sl-anchor-icon-space: calc(var(--sl-anchor-icon-size) + var(--sl-anchor-icon-gap));
    line-height: 1.25rem;
  }

  .sl-markdown-content .sl-anchor-link {
    color: color-mix(in oklab, var(--foreground) 40%, transparent);
  }

  /* code inline */
  .sl-markdown-content :not(pre) > code {
    background: var(--muted);
    border-radius: calc(var(--radius) - 4px);
    padding: 0.25rem 0.5rem;
    font-size: 0.875em;
  }

  /* code blocks */
  .expressive-code .ec-line :where(span[style^='--']:not([class])),
  :root:not([data-theme='dark']) .expressive-code[data-theme='dark'] .ec-line :where(span[style^='--']:not([class])) {
    font-size: 0.933em;
  }

  /* kbd styles */
  .sl-markdown-content kbd {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: inherit;
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 1;
    min-width: 1.25rem;
    min-height: 1.25rem;
    padding: 0.15rem 0.35rem;
    border-radius: calc(var(--radius) - 4px);
    border: 1px solid var(--border);
    background: var(--secondary);
    color: var(--foreground);
  }

  /* built-in Starlight FileTree */
  .sl-markdown-content starlight-file-tree {
    border: 0;
    border-radius: var(--radius);
    background-color: var(--code-background);
  }

  .sl-markdown-content starlight-file-tree :is(.directory > details > summary, .file) {
    color: var(--foreground);
  }

  .sl-markdown-content starlight-file-tree :is(.empty, .comment) {
    color: var(--muted-foreground);
  }

  .sl-markdown-content starlight-file-tree ul {
    border-inline-start-color: var(--border);
  }

  .sl-markdown-content
    starlight-file-tree
    :is(.directory > details > summary::marker, .directory > details > summary::-webkit-details-marker) {
    color: var(--muted-foreground);
  }

  .sl-markdown-content starlight-file-tree svg {
    fill: var(--muted-foreground);
  }

  .sl-markdown-content starlight-file-tree .directory > details > summary:hover {
    border-radius: calc(var(--radius) - 4px);
    background-color: color-mix(in oklab, var(--accent) 60%, transparent);
  }

  .sl-markdown-content
    starlight-file-tree
    :is(.directory > details > summary:hover, .directory > details > summary:hover .tree-icon) {
    color: var(--foreground);
    fill: currentColor;
  }

  .sl-markdown-content starlight-file-tree .directory > details > summary:hover ~ ul {
    border-inline-start-color: var(--ring);
  }

  .sl-markdown-content starlight-file-tree .highlight {
    border-radius: calc(var(--radius) - 4px);
    padding-inline: calc(var(--spacing) * 1.5);
    color: var(--foreground);
    background-color: var(--secondary);
  }

  .sl-markdown-content starlight-file-tree .highlight svg.tree-icon {
    fill: currentColor;
  }

  /* built-in Starlight Cards and LinkCards */
  .sl-markdown-content .card-grid {
    gap: 1rem;
  }

  .sl-markdown-content :is(.card, .sl-link-card) {
    border: 0;
    border-radius: calc(var(--radius) + 0.25rem);
    padding: 1.5rem;
    background-color: var(--code-background);
    box-shadow: none;
    transition: background-color 0.15s;
  }

  .sl-markdown-content :is(.card, .sl-link-card):hover {
    background-color: color-mix(in oklab, var(--code-background) 75%, var(--secondary));
  }

  .sl-markdown-content .card {
    --card-icon-background: var(--secondary);
    gap: 0.75rem;
  }

  .sl-markdown-content .card:nth-child(4n + 1) {
    --card-icon-background: color-mix(in oklab, var(--sl-color-orange) 18%, var(--secondary));
  }
  .sl-markdown-content .card:nth-child(4n + 2) {
    --card-icon-background: color-mix(in oklab, var(--sl-color-purple) 18%, var(--secondary));
  }
  .sl-markdown-content .card:nth-child(4n + 3) {
    --card-icon-background: color-mix(in oklab, var(--sl-color-green) 18%, var(--secondary));
  }
  .sl-markdown-content .card:nth-child(4n + 4) {
    --card-icon-background: color-mix(in oklab, var(--sl-color-red) 18%, var(--secondary));
  }

  .sl-markdown-content .card .title {
    gap: 0.75rem;
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1.25rem;
    color: var(--foreground);
  }

  .sl-markdown-content .card .icon {
    border: 0;
    box-sizing: content-box;
    width: 1rem;
    height: 1rem;
    padding: 0.5rem;
    border-radius: calc(var(--radius) - 2px);
    color: var(--foreground);
    background-color: var(--card-icon-background);
  }

  .sl-markdown-content .card:nth-child(n) {
    --sl-card-border: var(--border);
    --sl-card-bg: var(--secondary);
  }

  .sl-markdown-content .card .body {
    font-size: 0.875rem;
    line-height: 1.625rem;
    color: var(--muted-foreground);
  }

  .sl-markdown-content .sl-link-card {
    gap: 0.75rem;
    align-items: start;
  }

  .sl-markdown-content .sl-link-card .stack {
    gap: 0.25rem;
  }

  .sl-markdown-content .sl-link-card .title {
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1.25rem;
    color: var(--foreground);
  }

  .sl-markdown-content .sl-link-card .description {
    font-size: 0.875rem;
    line-height: 1.625rem;
    color: var(--muted-foreground);
  }

  .sl-markdown-content .sl-link-card .icon {
    color: var(--muted-foreground);
  }

  .sl-markdown-content .sl-link-card:hover .icon {
    color: var(--foreground);
  }

  /* built-in Starlight Asides */
  .sl-markdown-content .starlight-aside {
    --aside-background: var(--code-background);
    --aside-border: var(--border);
    --aside-title: var(--foreground);
    --aside-content: var(--muted-foreground);
    padding: 0.875rem 1rem;
    border: 1px solid var(--aside-border);
    border-inline-start: 1px solid var(--aside-border);
    border-radius: calc(var(--radius) * 1.8);
    background-color: var(--aside-background);
    color: var(--aside-content);
  }

  .sl-markdown-content .starlight-aside--note {
    --aside-background: color-mix(in oklab, var(--sl-color-blue-low) 78%, var(--code-background));
    --aside-border: color-mix(in oklab, var(--sl-color-blue) 45%, var(--border));
    --aside-title: var(--sl-color-blue-high);
    --aside-content: color-mix(in oklab, var(--sl-color-blue-high) 72%, var(--foreground));
  }

  .sl-markdown-content .starlight-aside--tip {
    --aside-background: color-mix(in oklab, var(--sl-color-purple-low) 78%, var(--code-background));
    --aside-border: color-mix(in oklab, var(--sl-color-purple) 45%, var(--border));
    --aside-title: var(--sl-color-purple-high);
    --aside-content: color-mix(in oklab, var(--sl-color-purple-high) 72%, var(--foreground));
  }

  .sl-markdown-content .starlight-aside--caution {
    --aside-background: color-mix(in oklab, var(--sl-color-orange-low) 82%, var(--code-background));
    --aside-border: color-mix(in oklab, var(--sl-color-orange) 48%, var(--border));
    --aside-title: var(--sl-color-orange-high);
    --aside-content: color-mix(in oklab, var(--sl-color-orange-high) 72%, var(--foreground));
  }

  .sl-markdown-content .starlight-aside--danger {
    --aside-background: color-mix(in oklab, var(--sl-color-red-low) 80%, var(--code-background));
    --aside-border: color-mix(in oklab, var(--sl-color-red) 48%, var(--border));
    --aside-title: var(--sl-color-red-high);
    --aside-content: color-mix(in oklab, var(--sl-color-red-high) 72%, var(--foreground));
  }

  .sl-markdown-content .starlight-aside__title {
    gap: 0.625rem;
    align-items: center;
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 1.25rem;
    color: var(--aside-title);
  }

  .sl-markdown-content .starlight-aside__icon {
    width: 1rem;
    height: 1rem;
    font-size: 1rem;
    flex-shrink: 0;
    color: var(--aside-title);
  }

  .sl-markdown-content .starlight-aside__title + .starlight-aside__content {
    margin-top: calc(var(--spacing) * 1.5);
  }

  .sl-markdown-content .starlight-aside__content {
    font-size: 0.875rem;
    line-height: 1.625rem;
    color: var(--aside-content);
  }

  .sl-markdown-content .starlight-aside__content a {
    color: var(--aside-title);
    text-decoration-color: color-mix(in oklab, var(--aside-title) 45%, transparent);
  }

  .sl-markdown-content .starlight-aside__content a:hover {
    text-decoration-color: currentColor;
  }

  /* built-in Starlight Badges */
  .sl-markdown-content .sl-badge {
    --badge-background: var(--secondary);
    --badge-foreground: var(--secondary-foreground);
    --badge-border: transparent;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.25rem;
    min-height: 1.25rem;
    padding: 0.125rem 0.5rem;
    border: 1px solid var(--badge-border);
    border-radius: 9999px;
    font-family: inherit;
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 1;
    color: var(--badge-foreground);
    background-color: var(--badge-background);
    vertical-align: middle;
  }

  .sl-markdown-content .sl-badge.default {
    --badge-background: var(--secondary);
    --badge-foreground: var(--secondary-foreground);
  }

  .sl-markdown-content .sl-badge.note {
    --badge-background: color-mix(in oklab, var(--sl-color-blue-low) 88%, var(--code-background));
    --badge-foreground: var(--sl-color-blue-high);
  }

  .sl-markdown-content .sl-badge.success {
    --badge-background: color-mix(in oklab, var(--sl-color-green-low) 88%, var(--code-background));
    --badge-foreground: var(--sl-color-green-high);
  }

  .sl-markdown-content .sl-badge.tip {
    --badge-background: color-mix(in oklab, var(--sl-color-purple-low) 88%, var(--code-background));
    --badge-foreground: var(--sl-color-purple-high);
  }

  .sl-markdown-content .sl-badge.caution {
    --badge-background: color-mix(in oklab, var(--sl-color-orange-low) 90%, var(--code-background));
    --badge-foreground: var(--sl-color-orange-high);
  }

  .sl-markdown-content .sl-badge.danger {
    --badge-background: color-mix(in oklab, var(--sl-color-red-low) 90%, var(--code-background));
    --badge-foreground: var(--sl-color-red-high);
  }

  .sl-markdown-content .sl-badge.small {
    min-height: 1.25rem;
    padding-inline: calc(var(--spacing) * 2);
    font-size: 0.75rem;
  }
  .sl-markdown-content .sl-badge.medium {
    min-height: 1.375rem;
    padding-inline: calc(var(--spacing) * 2.5);
    font-size: 0.75rem;
  }
  .sl-markdown-content .sl-badge.large {
    min-height: 1.5rem;
    padding-inline: calc(var(--spacing) * 3);
    font-size: 0.8125rem;
  }

  .sidebar-content .sl-badge {
    font-family: inherit;
    font-size: 0.6875rem;
    font-weight: 500;
    line-height: 1;
    min-height: 1.125rem;
    padding: 0.125rem 0.4375rem;
    border-radius: 9999px;
  }

  .sidebar-content a[aria-current='page'] > .sl-badge {
    background-color: color-mix(in oklab, currentColor 12%, transparent);
    border-color: transparent;
    color: inherit;
  }

  /* built-in Starlight LinkButtons */
  .sl-link-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.375rem;
    height: 2rem;
    padding: 0 0.75rem;
    border: 1px solid transparent;
    border-radius: var(--radius);
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1;
    white-space: nowrap;
    text-decoration: none;
    transition-property: color, background-color, border-color, box-shadow;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
    transition-duration: 0.15s;
    outline: none;
    outline-offset: 0.25rem;
    box-shadow: none;
  }

  .sl-link-button:hover {
    text-decoration: none;
  }

  .sl-link-button:focus-visible {
    border-color: var(--ring);
    box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 35%, transparent);
  }

  .sl-link-button svg {
    width: 1rem;
    height: 1rem;
    flex-shrink: 0;
  }

  .sl-link-button.primary {
    color: var(--primary-foreground);
    background-color: var(--primary);
    border-color: transparent;
  }

  .sl-link-button.primary:hover {
    color: var(--primary-foreground);
    background-color: color-mix(in oklab, var(--primary) 88%, var(--background));
  }

  .sl-link-button.secondary {
    color: var(--foreground);
    background-color: color-mix(in oklab, var(--background) 82%, var(--secondary));
    border-color: var(--border);
  }

  .sl-link-button.secondary:hover {
    color: var(--foreground);
    background-color: var(--accent);
  }

  .sl-link-button.minimal {
    color: var(--foreground);
    background-color: transparent;
    border-color: transparent;
  }

  .sl-link-button.minimal:hover {
    color: var(--accent-foreground);
    background-color: var(--accent);
  }

  /* built-in Starlight Steps */
  .sl-markdown-content .sl-steps {
    --bullet-size: 1.75rem;
    --bullet-margin: 0.25rem;
    margin-block: calc(var(--spacing) * 6) calc(var(--spacing) * 8);
  }

  .sl-markdown-content .sl-steps > li {
    padding-inline-start: calc(var(--bullet-size) + 1rem);
    padding-bottom: calc(var(--spacing) * 4);
    min-height: calc(var(--bullet-size) + var(--bullet-margin));
  }

  .sl-markdown-content .sl-steps > li::before {
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--muted-foreground);
    background-color: var(--muted);
    box-shadow: none;
  }

  .sl-markdown-content .sl-steps > li::after {
    background-color: var(--border);
  }

  .sl-markdown-content .sl-steps > li:last-child {
    padding-bottom: 0;
  }

  .sl-markdown-content .sl-steps > li:last-child::after {
    display: none;
  }

  .sl-markdown-content .sl-steps > li > .sl-heading-wrapper {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    height: var(--bullet-size);
    min-height: var(--bullet-size);
    transform: none;
    margin-bottom: 0;
  }

  .sl-markdown-content .sl-steps > li > .sl-heading-wrapper :is(h3, h4) {
    font-size: 1rem;
    line-height: 1.75rem;
    font-weight: 500;
    margin: 0;
  }

  .sl-markdown-content .sl-steps > li > .sl-heading-wrapper .sl-anchor-link {
    height: var(--bullet-size);
    line-height: var(--bullet-size);
    align-items: center;
  }

  .sl-markdown-content .sl-steps > li > .sl-heading-wrapper .sl-anchor-icon > svg {
    vertical-align: middle;
    transform: none;
  }

  .sl-markdown-content .sl-steps > li > p {
    color: var(--muted-foreground);
  }

  .sl-markdown-content .sl-steps > li > .sl-heading-wrapper + p {
    margin-top: 0;
  }

  /* built-in Starlight Tabs */
  .sl-markdown-content starlight-tabs {
    [role='tablist'] {
      border-bottom: 2px solid transparent;
    }

    .tab > [role='tab'] {
      --sl-tab-color-border: transparent;
    }

    .tab > [role='tab'][aria-selected='true'] {
      --sl-tab-color-border: var(--sl-color-text-accent);
    }

    /* Tabs with Expressive Code */
    &:has(> [role='tabpanel'] > .expressive-code) {
      display: block;
      margin-block: calc(var(--spacing) * 6) calc(var(--spacing) * 8);

      .tablist-wrapper {
        overflow-x: auto;
        padding: 0.25rem 0.75rem;
        border-radius: calc(var(--radius) + 0.25rem) calc(var(--radius) + 0.25rem) 0 0;
        background-color: var(--code-background);
        box-shadow: inset 0 -1px 0 color-mix(in oklab, var(--border) 85%, transparent);
        padding-block: calc(var(--spacing) * 1);
        padding-inline: calc(var(--spacing) * 3);
      }

      [role='tablist'] {
        display: flex;
        align-items: center;
        gap: 0.25rem;
        min-width: max-content;
        border-bottom: 0;
        padding: 0;
      }

      .tab > [role='tab'] {
        display: inline-flex;
        align-items: center;
        gap: 0.375rem;
        min-height: 1.75rem;
        padding: 0.125rem 0.5rem 0.25rem;
        border-radius: calc(var(--radius) - 2px);
        color: color-mix(in oklab, var(--foreground) 60%, transparent);
        font-size: 0.875rem;
        font-weight: 500;
        line-height: 1.25rem;
        box-shadow: none;
        transition-property: color, background-color, box-shadow;
        transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
        transition-duration: 0.15s;

        &:hover {
          color: var(--foreground);
          background-color: color-mix(in oklab, var(--background) 35%, transparent);
        }

        &:focus-visible {
          outline: none;
          box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 35%, transparent);
        }

        &[aria-selected='true'] {
          color: var(--foreground);
          background-color: var(--background);
          box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--border) 70%, transparent);
        }

        svg {
          width: 0.875rem;
          height: 0.875rem;
          color: currentColor;
        }
      }

      .tablist-wrapper ~ [role='tabpanel'] {
        margin-top: 0;
        padding: 1rem;
        border-radius: 0 0 calc(var(--radius) + 0.25rem) calc(var(--radius) + 0.25rem);
        background-color: var(--code-background);

        & > :first-child {
          margin-top: 0;
        }
        & > :last-child {
          margin-bottom: 0;
        }

        :is(pre, figure) {
          margin: 0;
        }
        p {
          color: color-mix(in oklab, var(--foreground) 72%, var(--muted-foreground));
        }

        & > .expressive-code {
          margin: -1rem;

          .frame {
            --button-spacing: 0.4rem;
            border: 0;
            border-radius: 0 0 calc(var(--radius) + 0.25rem) calc(var(--radius) + 0.25rem);
          }

          .header {
            display: none;
          }
          pre {
            border-radius: 0 0 calc(var(--radius) + 0.25rem) calc(var(--radius) + 0.25rem);
          }
        }
      }
    }
  }
}

theme-black/styles/theme.css.content:
@layer black {
  :root:root {
    --sl-font: var(--font-geist);
    --sl-font-mono: var(--font-geist-mono);
  }

  :root[data-theme='dark'] {
    /* starlight gray scale */
    --foreground: oklch(98.5% 0 0); /* neutral-50 */
    --gray-1: oklch(98.5% 0 0); /* neutral-50 */
    --gray-2: oklch(87% 0 0); /* neutral-300 */
    --gray-3: oklch(70.8% 0 0); /* neutral-400 */
    --gray-4: oklch(55.6% 0 0); /* neutral-500 */
    --gray-5: oklch(37.1% 0 0); /* neutral-700 */
    --gray-6: oklch(26.9% 0 0); /* neutral-800 */
    --gray-7: oklch(20.5% 0 0); /* neutral-900 */
    --background: oklch(14.5% 0 0); /* neutral-950 */

    /* colors */
    --orange-low: oklch(40.8% 0.123 38.172);
    --orange: oklch(83.7% 0.128 66.29);
    --orange-high: oklch(90.1% 0.076 70.697);
    --green-low: oklch(26.6% 0.065 152.934);
    --green: oklch(79.2% 0.209 151.711);
    --green-high: oklch(87.1% 0.15 154.449);
    --blue-low: oklch(29.3% 0.066 243.157);
    --blue: oklch(70.7% 0.165 254.624);
    --blue-high: oklch(82.8% 0.111 230.318);
    --purple-low: oklch(29.1% 0.149 302.717);
    --purple: oklch(71.4% 0.203 305.504);
    --purple-high: oklch(82.7% 0.119 306.383);
    --red-low: oklch(25.8% 0.092 26.042);
    --red: oklch(70.4% 0.191 22.216);
    --red-high: oklch(80.8% 0.114 19.571);

    --selection: oklch(0.922 0 0);
    --selection-foreground: oklch(0.205 0 0);
  }

  :root[data-theme='light'] {
    /* starlight gray scale */
    --foreground: oklch(14.5% 0 0); /* neutral-950 */
    --gray-1: oklch(20.5% 0 0); /* neutral-900 */
    --gray-2: oklch(26.9% 0 0); /* neutral-800 */
    --gray-3: oklch(37.1% 0 0); /* neutral-700 */
    --gray-4: oklch(55.6% 0 0); /* neutral-500 */
    --gray-5: oklch(70.8% 0 0); /* neutral-400 */
    --gray-6: oklch(87% 0 0); /* neutral-300 */
    --gray-7: oklch(97% 0 0); /* neutral-100 */
    --background: oklch(100% 0 0); /* white */

    /* colors */
    --orange-low: oklch(98% 0.016 73.684);
    --orange: oklch(70.5% 0.213 47.604);
    --orange-high: oklch(55.3% 0.195 38.402);
    --green-low: oklch(98.2% 0.018 155.826);
    --green: oklch(72.3% 0.219 149.579);
    --green-high: oklch(52.7% 0.154 150.069);
    --blue-low: oklch(97% 0.014 254.604);
    --blue: oklch(68.5% 0.169 237.323);
    --blue-high: oklch(48.8% 0.243 264.376);
    --purple-low: oklch(97.7% 0.014 308.299);
    --purple: oklch(62.7% 0.265 303.9);
    --purple-high: oklch(49.6% 0.265 301.924);
    --red-low: oklch(97.1% 0.013 17.38);
    --red: oklch(63.7% 0.237 25.331);
    --red-high: oklch(50.5% 0.213 27.518);

    /* light overrides */
    --accent: var(--gray-7);
    --secondary: var(--gray-7);
    --muted-foreground: var(--gray-4);
    --popover-background: var(--background);

    --selection: oklch(0% 0 0);
    --selection-foreground: oklch(1 0 0);
  }
}
